// 战法报名只读门：同tick迟答不倒填、五类门槛共用原Study、旧商铺边界不被放宽。
#include "resident/domains/growth/growth_tactic_lesson_qualification.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
Integer checks=0;
void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}
// 已验Study载荷的最小因果输入；本测试不声称完成真实课程或World。
StudyFact course(const StableId& skill,Integer tick,Integer before,Integer gain){StudyFact f;f.actor_id="student";f.start_tick=tick-1;f.phase="completed";f.completed_tick=tick;f.terms.student_id=f.actor_id;f.terms.skill_id=skill;f.terms.xp_before=before;f.terms.xp_limit=1200;f.terms.settlement_policy="per_lesson_v1";StudyLesson l;l.segment=StudySegment{1,tick,before,10000,gain,false,{},{}};f.lessons.push_back(l);return f;}
}
int main(){try{
 auto catalog=std::make_shared<CommonCatalog>();catalog->actor_ids={"student"};catalog->actor_initial_birth.insert("student",-14400);FamilyCatalog family;IdentityPrototype original;original.skills.tactics=290;original.skills.commerce=300;original.skills.infantry=100;original.skills.archery=100;original.skills.cavalry=300;original.skills.transport=300;family.prototypes.insert("student",original);FamilyState identities;GrowthSkillOriginContext origins{*catalog,family,identities,nullptr};
 CommonState seed;seed.identity.tick=4;seed.next_instance_id=100;ActorRecord actor;actor.id="student";actor.skills=original.skills;actor.skills.tactics=330;seed.actors.insert(actor.id,actor);CommonStore common(seed,catalog);GrowthState growth;growth.facts.insert("action:80",course("tactics",3,290,10));common.state().facts.insert("action:80",{"action:80","skill_study","cultivation"});common.state().facts.insert("tactic_lesson:10",{"tactic_lesson:10","tactic_lesson_started","growth_tactic_lessons"});growth.facts.insert("action:5",course("tactics",4,300,30));common.state().facts.insert("action:5",{"action:5","skill_study","cultivation"});const auto before=encode_common_state(common.state());
 auto current=read_growth_tactic_lesson_qualification(common,origins,growth,"student","tactics");check(current.ok&&current.value.minimum_xp==300&&current.value.minimum_level==2,"strict prior-tick Study proves minimum level");check(current.value.study_source_ids==std::vector<StableId>{"action:80"},"same tick course is excluded");auto old=read_growth_tactic_lesson_qualification_before_start(common,origins,growth,"student","tactics",3,"tactic_lesson:10");check(old.ok&&old.value.minimum_xp==290,"same tick earlier completion cannot be guessed");
 auto boundary=read_growth_tactic_lesson_qualification_before_start(common,origins,growth,"student","tactics",4,"tactic_lesson:10");check(boundary.ok&&boundary.value.minimum_xp==300,"later same tick course cannot change old start");for(const auto* skill:{"infantry","archery","cavalry","transport"})check(read_growth_tactic_lesson_qualification(common,origins,growth,"student",skill).ok,"fixed prerequisite skill accepted");
 check(!read_growth_tactic_lesson_qualification(common,origins,growth,"student","commerce").ok,"new reader does not accept arbitrary skill");check(!read_growth_tactic_lesson_qualification_before_start(common,origins,growth,"student","tactics",4,{}).ok,"actual start required");check(!read_commerce_study_qualification_before_opening(common,origins,growth,"student",4,"tactic_lesson:10").ok,"original shop reader keeps exact boundary");check(!read_growth_tactic_lesson_qualification_before_start(common,origins,growth,"student","tactics",5,"tactic_lesson:10").ok,"future observation refused");
 common.state().facts.find("tactic_lesson:10")->kind="tactic_lesson_closed";check(!read_growth_tactic_lesson_qualification_before_start(common,origins,growth,"student","tactics",4,"tactic_lesson:10").ok,"terminal source cannot impersonate start");common.state().facts.find("tactic_lesson:10")->kind="tactic_lesson_started";
 auto* later=std::get_if<StudyFact>(growth.facts.find("action:5"));later->start_tick=1;later->lessons[0].segment->settled_tick=2;check(!read_growth_tactic_lesson_qualification_before_start(common,origins,growth,"student","tactics",4,"tactic_lesson:10").ok,"later head cannot claim earlier qualifying credit");later->start_tick=3;later->lessons[0].segment->settled_tick=4;
 common.state().facts.find("action:80")->domain="interaction";check(!read_growth_tactic_lesson_qualification(common,origins,growth,"student","tactics").ok,"wrong original source domain refused");common.state().facts.find("action:80")->domain="cultivation";check(compare_boundary(before,encode_common_state(common.state())).exact(),"all reads preserve Common bytes");
 std::cout<<"GROWTH_TACTIC_LESSON_QUALIFICATION "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
